def clean_space(text):
    return re.sub(r"\s+", " ", str(text or "")).strip()


def clean_zh(value):
    value = clean_space(value)
    if value.startswith("[") or value.startswith("{"):
        return ""
    return re.sub(r"^(?:adj|adv|n|v|prep|conj|pron)\.(?:/[a-z.]+)?\s*", "", value)


def valid_example(example, example_zh):
    if not example or not example_zh:
        return False
    if len(re.findall(r"[A-Za-z]", example)) < 4:
        return False
    if not re.search(r"[\u4e00-\u9fff]", example_zh):
        return False
    lowered = example.lower()
    return not any(pattern in lowered for pattern in POLLUTION)


def valid_phrase(phrase, phrase_zh):
    phrase = clean_space(phrase)
    phrase_zh = clean_space(phrase_zh)
    if not phrase or not phrase_zh:
        return False
    lowered = phrase.lower()
    combined = f"{lowered} {phrase_zh}"
    if any(pattern in combined for pattern in POLLUTION):
        return False
    bad_bits = (
        "related evidence",
        "important evidence",
        "high-value academic",
        "academic reading",
        "precise idea",
        "word family",
        "word network",
        " structural change",
        " institutional change",
        " social change",
        " mechanism",
        " framework",
        " 结构变化",
        " 制度变化",
        " 社会变化",
        " 机制",
        " 框架",
    )
    return not any(bit in combined for bit in bad_bits)


def split_header_entries(text):
    pattern = re.compile(r"(?:^|\s)([A-Za-z][A-Za-z-]*)\s+\[([^\]]{2,40})\]\s+")
    starts = [m.start(1) for m in pattern.finditer(text)]
    if not starts:
        return []
    starts.append(len(text))
    return [text[starts[i]:starts[i + 1]].strip() for i in range(len(starts) - 1)]


def parse_header(text):
    match = re.match(r"^([A-Za-z][A-Za-z-]*)\s+\[([^\]]+)\]\s+(.+)$", text)
    if not match:
        return None
    return {
        "word": match.group(1).lower(),
        "ipa": clean_space(match.group(2)),
        "raw_meaning": clean_space(match.group(3)),
        "body": [],
    }


def parse_toefl_docx():
    doc = Document(str(TOEFL_DOCX))
    entries = {}
    current = None
    for para in doc.paragraphs:
        text = clean_space(para.text)
        if not text:
            continue
        chunks = split_header_entries(text)
        if chunks and re.match(r"^[A-Za-z][A-Za-z-]*\s+\[", chunks[0]):
            for chunk in chunks:
                item = parse_header(chunk)
                if not item:
                    continue
                current = item
                entries.setdefault(item["word"], item)
            continue
        if current:
            current["body"].append(text)
    return entries


def parse_meanings(raw):
    raw = raw.replace("[pl. curricula]", "").replace("[pl.", "")
    raw = re.sub(r"(?<=[\u4e00-\u9fff）)])\s*(vt\.|vi\.|ad\.|a\.|n\.|v\.|prep\.|conj\.|pron\.)", r"；\1", raw)
    raw = re.sub(r"（([^）]*[A-Za-z][^）]*)）", lambda m: " (" + m.group(1).replace("*", "") + ")", raw)
    chunks = []
    current_pos = ""
    for piece in re.split(r"；", raw):
        piece = clean_space(piece)
        if not piece:
            continue
        pos_match = re.match(r"^(vt\.|vi\.|ad\.|a\.|n\.|v\.|prep\.|conj\.|pron\.)\s*(.+)$", piece)
        if pos_match:
            current_pos = POS_MAP.get(pos_match.group(1), pos_match.group(1))
            piece = pos_match.group(2)
        syn = ""
        syn_match = re.search(r"\(([^()]*[A-Za-z][^()]*)\)$", piece)
        if syn_match:
            syn = syn_match.group(1).replace("*", "").strip()
            piece = piece[: syn_match.start()].strip()
        zh = clean_space(re.sub(r"\([^)]*\)", "", piece))
        if zh:
            chunks.append({"pos": current_pos or "?", "zh": zh, "syn": syn, "phrases": []})
    return chunks[:4]


def parse_cut(body):
    for line in body:
        if line.startswith("【记】"):
            text = line.replace("【记】", "").strip()
            text = re.sub(r"^(词根记忆|分拆联想|联想记忆|发音记忆|组合词)：", "", text)
            if any(marker in text for marker in ("音似", "谐音", "看作", "“", "”", "联想")):
                continue
            if "→" not in text and "＋" not in text:
                continue
            left, _, right = text.partition("→")
            pieces = [p.strip() for p in re.split(r"[＋+]", left) if p.strip()]
            cut = []
            gloss = []
            for piece in pieces:
                match = re.match(r"^([A-Za-z-]+)（([^）]+)）$", piece)
                if match:
                    cut.append(match.group(1))
                    gloss.append(match.group(2))
                else:
                    cut.append(re.sub(r"[^A-Za-z-]", "", piece) or piece)
                    gloss.append(piece)
            if cut:
                return ["/".join(cut), "/".join(gloss)]
    return []


def parse_phrases(body):
    phrases = []
    for line in body:
        if not line.startswith("【搭】"):
            continue
        text = line.replace("【搭】", "")
        for piece in re.split(r"[；;]", text):
            piece = clean_space(piece)
            if not piece:
                continue
            match = re.match(r"^(.+?)\s+([\u4e00-\u9fff].*)$", piece)
            if match:
                phrase = clean_space(match.group(1).replace("＝", "="))
                zh = clean_space(match.group(2))
                if valid_phrase(phrase, zh):
                    phrases.append((phrase, zh))
    return phrases[:6]


def load_old_registry():
    text = (ROOT / "data/vocab/VOCAB_WORD_CONTENT_REGISTRY_LITE.js").read_text(encoding="utf8")
    payload = json.loads(text[text.index("=") + 1 :].strip().rstrip(";"))
    out = {}
    for word, card in payload["cards"].items():
        phrases = []
        for phrase in card.get("phrases", []):
            en = clean_space(phrase.get("phrase"))
            zh = clean_space(phrase.get("phrase_zh"))
            if valid_phrase(en, zh) and "[" not in zh and "]" not in zh and "Card" not in zh:
                phrases.append((en, zh))
        examples = []
        for example in card.get("examples", []):
            en = clean_space(example.get("example"))
            zh = clean_space(example.get("example_zh"))
            if valid_example(en, zh):
                examples.append((en, zh))
        out[word.lower()] = {
            "pos": "" if clean_space(card.get("pos")).startswith("[") else clean_space(card.get("pos")),
            "zh": clean_zh(card.get("zh")),
            "phrases": phrases,
            "examples": examples,
        }
    return out


def load_kin_glossary():
    out = {}
    total = AUDITS / "kin_repository_total.md"
    if total.exists():
        for line in total.read_text(encoding="utf8").splitlines():
            line = clean_space(line)
            if not line or line.startswith("#") or line.endswith("：") or line.endswith(":"):
                continue
            if "|" not in line or " " not in line:
                continue
            left, _, _rest = line.partition("|")
            word, _, zh = left.partition(" ")
            word = clean_space(word).lower()
            zh = clean_space(zh).strip("/；; ")
            if re.fullmatch(r"[a-z][a-z-]*", word) and zh:
                out.setdefault(word, {"zh": zh, "pos": "", "examples": []})

    cards = AUDITS / "kin_cluster_cards.md"
    if cards.exists():
        for line in cards.read_text(encoding="utf8").splitlines():
            line = clean_space(line)
            match = re.match(r"^-\s+([a-z][a-z-]*)\s+((?:n|v|adj|adv|prep|conj|pron)\.[^ ]*)?\s*(.+)$", line)
            if not match:
                continue
            word = match.group(1).lower()
            pos = clean_space(match.group(2) or "")
            zh = clean_space(match.group(3))
            zh = re.sub(r"\s+example:.*$", "", zh).strip()
            if zh:
                out.setdefault(word, {"zh": zh, "pos": pos, "examples": []})
    return out


