def load_entry_words():
    words = []
    sources = []
    universe = AUDITS / "big_card_word_universe.md"
    if universe.exists():
        sources.append(universe)
    else:
        sources.extend([AUDITS / "entry_total_big_cards.md", AUDITS / "entry_total_orphan_small_cards.md"])
    for source in sources:
        for line in source.read_text(encoding="utf8").splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split()
            if source.name == "big_card_word_universe.md" and not ({"reading-big", "toefl", "kin"} & set(parts)):
                continue
            word = WORD_ALIASES.get(parts[0].lower(), parts[0].lower())
            if word in SMALL_CARD_ONLY:
                continue
            if word not in words:
                words.append(word)
    return words


def add_unique_phrases(target, source):
    seen = {(p.lower(), z) for p, z in target}
    for phrase in source:
        if not valid_phrase(phrase[0], phrase[1]):
            continue
        key = (phrase[0].lower(), phrase[1])
        if key not in seen:
            target.append(phrase)
            seen.add(key)


