def fallback_gloss(zh):
    for needle, gloss in GLOSS_HINTS:
        if needle in zh:
            return gloss
    return ""


def clean_syn(value):
    value = clean_space(value)
    if not value:
        return ""
    bad = {"sense", "meaning", "word", "term"}
    parts = [p.strip() for p in re.split(r"[,;/]", value) if p.strip()]
    parts = [p for p in parts if p.lower() not in bad]
    return ", ".join(parts)


